#include <stdio.h>
#include <stdlib.h>

typedef struct BiTNode {
    char data;
    struct BiTNode *lchild, *rchild;
} BiTNode, *BiTree;

/* 按先序序列创建二叉链表，'#' 表示空子树，输入中可用空白分隔 */
void CreateBiTree(BiTree *T) {
    char ch;

    if (scanf(" %c", &ch) != 1 || ch == '#') {
        *T = NULL;
        return;
    }
    *T = (BiTree)malloc(sizeof(BiTNode));
    (*T)->data = ch;
    CreateBiTree(&(*T)->lchild);
    CreateBiTree(&(*T)->rchild);
}

int NodeCount(BiTree T) {
    if (T == NULL)
        return 0;
    return NodeCount(T->lchild) + NodeCount(T->rchild) + 1;
}

int LeafCount(BiTree T) {
    if (T == NULL)
        return 0;
    if (T->lchild == NULL && T->rchild == NULL)
        return 1;
    return LeafCount(T->lchild) + LeafCount(T->rchild);
}

int Depth(BiTree T) {
    int dl, dr;

    if (T == NULL)
        return 0;
    dl = Depth(T->lchild);
    dr = Depth(T->rchild);
    return dl > dr ? dl + 1 : dr + 1;
}

int main(void) {
    BiTree T = NULL;

    CreateBiTree(&T);
    printf("%d %d %d\n", NodeCount(T), LeafCount(T), Depth(T));
    return 0;
}

problems.stem:
下列程序统计二叉树中叶子结点（n0）、度为 1 的结点（n1）与度为 2 的结点（n2）的个数，并验证性质 n0 = n2 + 1。写出程序的运行结果。
```
#include <stdio.h>
#include <stdlib.h>

typedef struct BiTNode {
    char data;
    struct BiTNode *lchild, *rchild;
} BiTNode, *BiTree;

/* 按先序序列创建二叉链表，'#' 表示空子树，输入中可用空白分隔 */
void CreateBiTree(BiTree *T) {
    char ch;

    if (scanf(" %c", &ch) != 1 || ch == '#') {
        *T = NULL;
        return;
    }
    *T = (BiTree)malloc(sizeof(BiTNode));
    (*T)->data = ch;
    CreateBiTree(&(*T)->lchild);
    CreateBiTree(&(*T)->rchild);
}

void Count(BiTree T, int *n0, int *n1, int *n2) {
    if (T == NULL)
        return;
    if (T->lchild == NULL && T->rchild == NULL)
        (*n0)++;
    else if (T->lchild == NULL || T->rchild == NULL)
        (*n1)++;
    else
        (*n2)++;
    Count(T->lchild, n0, n1, n2);
    Count(T->rchild, n0, n1, n2);
}

int main(void) {
    BiTree T = NULL;
    int n0 = 0, n1 = 0, n2 = 0;

    CreateBiTree(&T);
    Count(T, &n0, &n1, &n2);
    printf("n0=%d n1=%d n2=%d\n", n0, n1, n2);
    printf("check=%d\n", n2 + 1);
    return 0;
}
```
运行时输入：
```
A B D # # # C E # # F # #
```

