#include <stdio.h>
#include <stdlib.h>

typedef struct BiTNode {
    char data;
    struct BiTNode *lchild, *rchild;
} BiTNode, *BiTree;

/* 按先序序列创建二叉链表，'#' 表示空子树，输入中可用空白分隔 */
void CreateBiTree(BiTree *T) {
    char ch;

    if (scanf(" %c", &ch) != 1 || ch == '#') {
        *T = NULL;
        return;
    }
    *T = (BiTree)malloc(sizeof(BiTNode));
    (*T)->data = ch;
    CreateBiTree(&(*T)->lchild);
    CreateBiTree(&(*T)->rchild);
}

int NodeCount(BiTree T) {
    if (T == NULL)
        return 0;
    return NodeCount(T->lchild) + NodeCount(T->rchild) + 1;
}

int Depth(BiTree T) {
    int dl, dr;

    if (T == NULL)
        return 0;
    dl = Depth(T->lchild);
    dr = Depth(T->rchild);
    return dl > dr ? dl + 1 : dr + 1;
}

/* 满二叉树：结点数恰为 2^深度 - 1 */
int IsFull(BiTree T) {
    int n, d, i, p = 1;

    n = NodeCount(T);
    d = Depth(T);
    for (i = 1; i <= d; i++)
        p = p * 2;
    return n == p - 1;
}

int main(void) {
    BiTree T = NULL;

    CreateBiTree(&T);
    printf("%d\n", IsFull(T));
    return 0;
}

