problems.stem:
下列程序用一维数组顺序存储完全二叉树，输出每个结点的值、度与左孩子值（无左孩子时输出 0）。写出程序的运行结果。
```
#include <stdio.h>

#define MAXN 100

int main(void) {
    int a[MAXN + 1];
    int n, i, d;

    if (scanf("%d", &n) != 1 || n < 0 || n > MAXN)
        return 1;
    for (i = 1; i <= n; i++)
        if (scanf("%d", &a[i]) != 1)
            return 1;
    for (i = 1; i <= n; i++) {
        d = 0;
        if (2 * i <= n)
            d++;
        if (2 * i + 1 <= n)
            d++;
        printf("%d:%d %d\n", a[i], d, 2 * i <= n ? a[2 * i] : 0);
    }
    return 0;
}
```
