#include <stdio.h>
#include <stdlib.h>

#define MAXN 200

typedef struct BiTNode {
    char data;
    struct BiTNode *lchild, *rchild;
} BiTNode, *BiTree;

void CreateBiTree(BiTree *T) {
    char ch;

    if (scanf(" %c", &ch) != 1 || ch == '#') {
        *T = NULL;
        return;
    }
    *T = (BiTree)malloc(sizeof(BiTNode));
    (*T)->data = ch;
    CreateBiTree(&(*T)->lchild);
    CreateBiTree(&(*T)->rchild);
}

/* 按完全二叉树编号把链表内容填入数组 a，*max 记录最大占用编号 */
void Fill(BiTree T, int idx, char a[], int *max) {
    if (T == NULL || idx >= MAXN)
        return;
    a[idx] = T->data;
    if (idx > *max)
        *max = idx;
    Fill(T->lchild, 2 * idx, a, max);
    Fill(T->rchild, 2 * idx + 1, a, max);
}

int main(void) {
    BiTree T = NULL;
    char a[MAXN];
    int max = 0, i;

    CreateBiTree(&T);
    for (i = 0; i < MAXN; i++)
        a[i] = '#';
    Fill(T, 1, a, &max);
    for (i = 1; i <= max; i++)
        printf("%c ", a[i]);
    printf("\n");
    return 0;
}

