#include <stdio.h>
#include <string.h>

#define MAXSIZE 100

/* 由先序 pre[pl..pr] 与中序 in[il..ir] 直接递归输出后序序列 */
void PostFromPreIn(char *pre, int pl, int pr, char *in, int il, int ir)
{
    int k, lsize;

    if (pl > pr)
        return;
    k = il;
    while (in[k] != pre[pl])
        k++;
    lsize = k - il;
    PostFromPreIn(pre, pl + 1, pl + lsize, in, il, k - 1);
    PostFromPreIn(pre, pl + lsize + 1, pr, in, k + 1, ir);
    printf("%c", pre[pl]);
}

int main(void)
{
    char pre[MAXSIZE], in[MAXSIZE];

    if (scanf("%99s%99s", pre, in) != 2)
        return 1;
    PostFromPreIn(pre, 0, (int)strlen(pre) - 1, in, 0, (int)strlen(in) - 1);
    printf("\n");

    return 0;
}

