#include <stdio.h>
#include <stdlib.h>

#define MAXSIZE 100

typedef struct BiTNode {
    char data;
    struct BiTNode *lchild, *rchild;
} BiTNode, *BiTree;

/* 按先序序列创建二叉链表，'#' 表示空子树 */
void CreateBiTree(BiTree *T) {
    char ch;

    if (scanf(" %c", &ch) != 1 || ch == '#') {
        *T = NULL;
        return;
    }
    *T = (BiTree)malloc(sizeof(BiTNode));
    (*T)->data = ch;
    CreateBiTree(&(*T)->lchild);
    CreateBiTree(&(*T)->rchild);
}

/* 递归求深度：左右子树深度的最大值加 1 */
int Depth(BiTree T) {
    int l, r;

    if (T == NULL)
        return 0;
    l = Depth(T->lchild);
    r = Depth(T->rchild);

    return (l > r ? l : r) + 1;
}

/* 层序遍历求最大宽度：last 标记本层最后一个元素之后的位置 */
int Width(BiTree T) {
    BiTree q[MAXSIZE];
    int front = 0, rear = 0, last, w = 0, maxw = 0;

    if (T == NULL)
        return 0;
    q[rear++] = T;
    last = rear;
    while (front < rear) {
        BiTree p = q[front++];

        w++;
        if (p->lchild != NULL)
            q[rear++] = p->lchild;
        if (p->rchild != NULL)
            q[rear++] = p->rchild;
        if (front == last) {
            if (w > maxw)
                maxw = w;
            w = 0;
            last = rear;
        }
    }

    return maxw;
}

int main(void) {
    BiTree T = NULL;

    CreateBiTree(&T);
    printf("%d %d\n", Depth(T), Width(T));

    return 0;
}

