#include <stdio.h>
#include <stdlib.h>

#define MAXSIZE 100

typedef struct BiTNode {
    char data;
    struct BiTNode *lchild, *rchild;
} BiTNode, *BiTree;

/* 按先序序列创建二叉链表，'#' 表示空子树 */
void CreateBiTree(BiTree *T) {
    char ch;

    if (scanf(" %c", &ch) != 1 || ch == '#') {
        *T = NULL;
        return;
    }
    *T = (BiTree)malloc(sizeof(BiTNode));
    (*T)->data = ch;
    CreateBiTree(&(*T)->lchild);
    CreateBiTree(&(*T)->rchild);
}

/* 判断两棵二叉树是否相同：相同返回 1，否则返回 0 */
int Same(BiTree a, BiTree b) {
    if (a == NULL && b == NULL)
        return 1;
    if (a == NULL || b == NULL)
        return 0;
    if (a->data != b->data)
        return 0;

    return Same(a->lchild, b->lchild) && Same(a->rchild, b->rchild);
}

int main(void) {
    BiTree T1 = NULL, T2 = NULL;

    CreateBiTree(&T1);
    CreateBiTree(&T2);
    if (Same(T1, T2))
        printf("YES\n");
    else
        printf("NO\n");

    return 0;
}

