#include <stdio.h>
#include <string.h>

#define MAXSIZE 100

/* 由中序 in[il..ir] 与后序 post[pl..pr] 直接递归输出先序序列 */
void PreFromInPost(char *in, int il, int ir, char *post, int pl, int pr)
{
    int k, lsize;

    if (il > ir)
        return;
    k = il;
    while (in[k] != post[pr])
        k++;
    lsize = k - il;
    printf("%c", post[pr]);
    PreFromInPost(in, il, k - 1, post, pl, pl + lsize - 1);
    PreFromInPost(in, k + 1, ir, post, pl + lsize, pr - 1);
}

int main(void)
{
    char in[MAXSIZE], post[MAXSIZE];

    if (scanf("%99s%99s", in, post) != 2)
        return 1;
    PreFromInPost(in, 0, (int)strlen(in) - 1, post, 0, (int)strlen(post) - 1);
    printf("\n");

    return 0;
}

