    char ch;

    if (scanf(" %c", &ch) != 1 || ch == '#') {
        *T = NULL;
        return;
    }
    *T = (BiThrTree)malloc(sizeof(BiThrNode));
    (*T)->data = ch;
    (*T)->ltag = 0;
    (*T)->rtag = 0;
    CreateBiThrTree(&(*T)->lchild);
    CreateBiThrTree(&(*T)->rchild);
}

/* 中序遍历的同时进行线索化：pre 指向刚刚访问过的结点 */
void InThreading(BiThrTree p) {
    if (p == NULL)
        return;
    /*__BLANK_1__*/;
    if (p->lchild == NULL) {
        p->ltag = 1;
        p->lchild = pre;
    }
    if (pre != NULL && pre->rchild == NULL) {
        pre->rtag = 1;
        /*__BLANK_2__*/;
    }
    /*__BLANK_3__*/;
    InThreading(p->rchild);
}

/* 中序线索化并增设头结点，*Thrt 返回头结点指针 */
void InOrderThreading(BiThrTree *Thrt, BiThrTree T) {
    *Thrt = (BiThrTree)malloc(sizeof(BiThrNode));
    if (*Thrt == NULL)
        exit(1);
    (*Thrt)->ltag = 0;
    (*Thrt)->rtag = 1;
    (*Thrt)->rchild = *Thrt;
    if (T == NULL)
        (*Thrt)->lchild = *Thrt;
    else {
        (*Thrt)->lchild = T;
        pre = *Thrt;
        InThreading(T);
        /*__BLANK_4__*/;
        pre->rtag = 1;
        (*Thrt)->rchild = pre;
    }
}

/* 利用线索非递归地中序遍历 */
void InOrderTraverse_Thr(BiThrTree Thrt) {
    BiThrTree p = Thrt->lchild;

    while (p != Thrt) {
        while (p->ltag == 0)
            p = p->lchild;
        printf("%c", p->data);
        while (p->rtag == 1 && p->rchild != Thrt) {
            p = p->rchild;
            printf("%c", p->data);
        }
        p = p->rchild;
    }
}

int main(void) {
    BiThrTree T = NULL, Th = NULL;

    CreateBiThrTree(&T);
    InOrderThreading(&Th, T);
    InOrderTraverse_Thr(Th);
    printf("\n");

    return 0;
}
