#include <stdio.h>
#include <stdlib.h>

#define MAXSIZE 100

typedef struct BiThrNode {
    char data;
    struct BiThrNode *lchild, *rchild;
    int ltag, rtag; /* tag 为 0 时指针指向孩子，为 1 时指向线索 */
} BiThrNode, *BiThrTree;

static BiThrTree pre = NULL; /* 始终指向中序序列中刚刚访问过的结点 */

/* 按先序序列创建二叉链表，'#' 表示空子树 */
void CreateBiThrTree(BiThrTree *T) {
    char ch;

    if (scanf(" %c", &ch) != 1 || ch == '#') {
        *T = NULL;
        return;
    }
    *T = (BiThrTree)malloc(sizeof(BiThrNode));
    (*T)->data = ch;
    (*T)->ltag = 0;
    (*T)->rtag = 0;
    CreateBiThrTree(&(*T)->lchild);
    CreateBiThrTree(&(*T)->rchild);
}

/* 中序遍历的同时进行线索化：pre 指向刚刚访问过的结点 */
void InThreading(BiThrTree p) {
    if (p == NULL)
        return;
    InThreading(p->lchild);
    if (p->lchild == NULL) {
        p->ltag = 1;
        p->lchild = pre;
    }
    if (pre != NULL && pre->rchild == NULL) {
        pre->rtag = 1;
        pre->rchild = p;
    }
    pre = p;
    InThreading(p->rchild);
}

/* 中序线索化并增设头结点，*Thrt 返回头结点指针 */
void InOrderThreading(BiThrTree *Thrt, BiThrTree T) {
    *Thrt = (BiThrTree)malloc(sizeof(BiThrNode));
    if (*Thrt == NULL)
        exit(1);
    (*Thrt)->ltag = 0;
    (*Thrt)->rtag = 1;
    (*Thrt)->rchild = *Thrt;
    if (T == NULL)
        (*Thrt)->lchild = *Thrt;
    else {
        (*Thrt)->lchild = T;
        pre = *Thrt;
        InThreading(T);
        pre->rchild = *Thrt;
        pre->rtag = 1;
        (*Thrt)->rchild = pre;
    }
}

