#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXN 60
#define MAXMSG 100
#define BITLEN (MAXMSG * MAXN)

typedef struct {
    unsigned int weight;
    unsigned int parent, lchild, rchild;
} HTNode, *HuffmanTree;

void Select(HuffmanTree HT, int k, int *s1, int *s2) {
    int i;

    *s1 = 0;
    *s2 = 0;
    for (i = 1; i <= k; i++) {
        if (HT[i].parent != 0)
            continue;
        if (*s1 == 0 || HT[i].weight < HT[*s1].weight) {
            *s2 = *s1;
            *s1 = i;
        } else if (*s2 == 0 || HT[i].weight < HT[*s2].weight)
            *s2 = i;
    }
}

void CreateHuffmanTree(HuffmanTree HT, int *w, int n) {
    int m, i, s1, s2;

    if (n < 1)
        return;
    m = 2 * n - 1;
    for (i = 1; i <= n; i++) {
        HT[i].weight = (unsigned int)w[i - 1];
        HT[i].parent = 0;
        HT[i].lchild = 0;
        HT[i].rchild = 0;
    }
    for (i = n + 1; i <= m; i++) {
        HT[i].weight = 0;
        HT[i].parent = 0;
        HT[i].lchild = 0;
        HT[i].rchild = 0;
    }
    for (i = n + 1; i <= m; i++) {
        Select(HT, i - 1, &s1, &s2);
        HT[s1].parent = i;
        HT[s2].parent = i;
        HT[i].lchild = s1;
        HT[i].rchild = s2;
        HT[i].weight = HT[s1].weight + HT[s2].weight;
    }
}

void MakeCode(HuffmanTree HT, int n, char HC[][MAXN]) {
    char cd[MAXN];
    int i, c, f, start;

    for (i = 1; i <= n; i++) {
        start = MAXN - 1;
        cd[start] = '\0';
        for (c = i, f = HT[i].parent; f != 0; c = f, f = HT[f].parent)
            cd[--start] = (HT[f].lchild == c) ? '0' : '1';
        strcpy(HC[i], &cd[start]);
    }
}

/* 把电文 msg 编码为 0/1 串存入 bits */
void Encode(char *msg, char HC[][MAXN], char *chs, int n, char *bits) {
    int i, j;

    bits[0] = '\0';
    for (i = 0; msg[i] != '\0'; i++) {
        for (j = 1; j <= n; j++)
            if (chs[j - 1] == msg[i])
                break;
        if (j > n)
            continue;
        strcat(bits, HC[j]);
    }
}

/* 译码：从根出发，遇 0 走左孩子、遇 1 走右孩子，走到叶子就输出该字符并回到根 */
void Decode(HuffmanTree HT, char *bits, char *chs, int n) {
    int p = 2 * n - 1, i = 0;

    while (bits[i] != '\0') {
        if (bits[i] == '0')
            p = HT[p].lchild;
        else
            p = HT[p].rchild;
        if (HT[p].lchild == 0 && HT[p].rchild == 0) {
            printf("%c", chs[p - 1]);
            p = 2 * n - 1;
        }
        i++;
    }
    printf("\n");
}

int main(void) {
    HuffmanTree HT;
    char HC[MAXN][MAXN], chs[MAXN], msg[MAXMSG], bits[BITLEN];
    int w[MAXN], n, i;

    if (scanf("%d", &n) != 1 || n < 2 || n > MAXN)
        return 1;
    if (scanf("%99s", chs) != 1)
        return 1;
    for (i = 0; i < n; i++)
        if (scanf("%d", &w[i]) != 1)
            return 1;
    if (scanf("%99s", msg) != 1)
        return 1;
    HT = (HuffmanTree)malloc((2 * MAXN) * sizeof(HTNode));
    if (HT == NULL)
        return 1;
    CreateHuffmanTree(HT, w, n);
    MakeCode(HT, n, HC);
    Encode(msg, HC, chs, n, bits);
    printf("%s\n", bits);
    Decode(HT, bits, chs, n);

    return 0;
}

